/// Событие, запустившее сценарий: принятое хуком или событие внутри Tungo.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AutomationHookEvent {
    /// Тело события как пришло: текст (обычно JSON строкой — разобрать JSON.parse) или base64 при encoding = base64
    pub body: Option<String>,
    /// Заголовок Content-Type запроса отправителя; null — его не было
    pub content_type: Option<String>,
    /// Как хранится body: `utf8` — текст как пришёл; `base64` — тело не текст UTF-8, хранится в base64
    pub encoding: Option<Box<AutomationHookEventEncoding>>,
    /// id события у отправителя (до 200 знаков): из тела по id_path хука, из заголовка Idempotency-Key или X-Event-Id, иначе sha256 тела. По нему отсеиваются повторы
    pub external_id: Option<String>,
    /// Хук, на который пришло событие; null — событие Tungo (source = tungo) (hk_…)
    pub hook_id: Option<String>,
    /// id события у нас — у хука тот же event_id, что вернул приём (hev_…)
    pub id: Option<String>,
    /// Когда событие принято, ISO 8601 UTC
    pub received_at: Option<String>,
    /// Размер тела в байтах
    pub size: Option<i64>,
    /// `hook` — событие пришло на хук; `tungo` — событие внутри Tungo (тело — как у вебхука этого события)
    pub source: Option<Box<AutomationHookEventSource>>,
    /// Вид события Tungo (esf.incoming.received, …); у хука — null
    pub r#type: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Как хранится body: `utf8` — текст как пришёл; `base64` — тело не текст UTF-8, хранится в base64
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AutomationHookEventEncoding {
    Utf8,
    Base64,
    UnknownValue(String),
}

impl AutomationHookEventEncoding {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Utf8 => "utf8",
            Self::Base64 => "base64",
            Self::UnknownValue(s) => s.as_str(),
        }
    }
}

/// `hook` — событие пришло на хук; `tungo` — событие внутри Tungo (тело — как у вебхука этого события)
