/// Хук с токеном — ответ на заведение и смену токена; токен больше нигде не показывается.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AutomationHookWithToken {
    /// Когда заведён, ISO 8601 UTC
    pub created_at: Option<String>,
    /// false — хук выключен: события на его адрес получают 404, как на неизвестный
    pub enabled: Option<bool>,
    /// id хука — для адресов …/automations/hooks/{id} и для trigger.hook_id сценария (hk_…)
    pub id: Option<String>,
    /// Путь через точку к id события в JSON тела (номер платежа у отправителя) — по нему отсеиваются повторы. null — id из заголовков Idempotency-Key / X-Event-Id или хеш тела
    pub id_path: Option<String>,
    /// Название хука для людей
    pub name: Option<String>,
    /// Путь API к сценариям компании: сценарии этого хука — те, у которых trigger.hook_id равен id хука
    pub scenarios_url: Option<String>,
    /// Заголовок, в котором отправитель присылает подпись (нижним регистром)
    pub signature_header: Option<String>,
    /// Задан ли секрет подписи: true — события без верной подписи отвергаются (401). Сам секрет не показывается никогда. По событиям хука без подписи автоодобрение ничего в 1С не пишет
    pub signed: Option<bool>,
    /// Токен хука (th_…, 46 знаков) — только в этом ответе: сохраните у отправителя. Кто знает токен, может слать события этой компании. null — повтор запроса с тем же Idempotency-Key: токен уже выдан первым ответом (token_note…
    pub token: Option<String>,
    /// Последние 4 знака токена после многоточия — узнать, какой адрес настроен у отправителя. Сам токен не хранится: потерян — POST …/hooks/{id}/rotate
    pub token_hint: Option<String>,
    /// Только в повторе с тем же Idempotency-Key: почему token и url — null и что делать (rotate)
    pub token_note: Option<String>,
    /// Когда менялся последний раз, ISO 8601 UTC
    pub updated_at: Option<String>,
    /// Полный адрес приёма событий (адрес API + `/hooks/{token}`) — его и дают отправителю. null — повтор с тем же Idempotency-Key
    pub url: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Ручной запуск; с event_id — пробный прогон на прошлом событии.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AutomationManualRun {
    /// Итоговый ответ ИИ — что сделано, текстом как в чате. null — ответа нет (ещё идёт, не удался или action: checks)
    pub answer: Option<String>,
    /// Номер попытки: 1, каждый повтор (retry) прибавляет 1
    pub attempt: Option<i64>,
    /// Сколько раз запуск уже повторялся сам после «1С не на связи»
    pub auto_retries: Option<i64>,
    /// true — отмена запрошена, идущий запуск остановится на ближайшем шаге (state станет cancelled)
    pub cancel_requested: Option<bool>,
    /// Стоимость запуска — расход ИИ с баланса платформы, в тиынах (1 ₸ = 100 тиын). 0 — ИИ не вызывался. Поле есть только у ключа API и у владельца и админа организации по сессии; остальным участникам его нет
    pub cost_tiyn: Option<i64>,
    /// Когда запуск поставлен в очередь, ISO 8601 UTC
    pub created_at: Option<String>,
    /// Номер шага (с 1), на котором запуск идёт, упал или отменён — с него продолжит повтор; null — запуск закончен успешно или шаги ещё не начинались
    pub current_step: Option<i64>,
    /// Почему запуск не удался или пропущен — текст для человека; null — ошибки нет
    pub error: Option<String>,
    /// Машинная причина ошибки: `onec_offline` — 1С не была на связи (программа в офисе или сервер 1С); null — другая причина или ошибки нет
    pub error_code: Option<String>,
    /// Событие (hev_…), которое запустило: у хука — тот же event_id, что вернул приём POST /hooks/{token}; подробности — event у GET …/runs/{id}. null — запуск не по событию
    pub event_id: Option<String>,
    /// Вид события Tungo, запустившего сценарий (trigger = event); null — запуск не по нему
    pub event_type: Option<String>,
    /// id этого события у отправителя (по id_path хука, Idempotency-Key, X-Event-Id или sha256 тела) — для сопоставления со своим заказом или платежом; у события Tungo — его id evt_… (тот же, что в вебхуке); у пробного события …
    pub external_id: Option<String>,
    /// Только при event_id. Подходит ли выбранное событие фильтру сценария. false — настоящая доставка такого события сценарий не запустила бы; прогон всё равно идёт: событие выбрали вы
    pub filter_matched: Option<bool>,
    /// Когда закончился, ISO 8601 UTC; null — ещё не закончился
    pub finished_at: Option<String>,
    /// id запуска: подробности — GET …/automations/runs/{id}; повторить упавший — POST …/runs/{id}/retry (run_…)
    pub id: Option<String>,
    /// Итог в форме сценария (output): поля — числа, да/нет, значения из списка и номера. Тот же итог — в вебхуке automation.run.completed. null — у сценария нет формы итога, ИИ итог не вернул или он не прошёл проверку (output_…
    pub output: Option<BTreeMap<String, f64>>,
    /// Почему итога нет: `not_returned` — ИИ его не отдал; `rejected` — отдал не в заданной форме (например, имя в поле номера). Запуск при этом не падает. null — итог есть или формы нет
    pub output_error: Option<Box<AutomationManualRunOutputError>>,
    /// То же словами для человека; null — итог есть или формы нет
    pub output_note: Option<String>,
    /// Предложения, подготовленные запуском (по всем попыткам)
    pub proposals: Option<Vec<Box<AutomationRunProposal>>>,
    /// Кто запросил запуск (usr_…) — при ручном запуске и повторе. null — запуск по хуку или расписанию: человека нет, смотрите trigger и run_as сценария
    pub requested_by: Option<String>,
    /// Когда запуск повторится сам (ISO 8601 UTC) — только при error_code = onec_offline, пока не кончились попытки настройки automations.retry; null — сам не повторится
    pub retry_at: Option<String>,
    /// true — запуск можно повторить (state = error): показать кнопку «Повторить» → POST …/runs/{id}/retry
    pub retryable: Option<bool>,
    /// Какой сценарий запущен (его могли удалить после запуска) (scn_…)
    pub scenario_id: Option<String>,
    /// Плановое время запуска по расписанию, ISO 8601 UTC; null — запуск не по расписанию
    pub slot_at: Option<String>,
    /// Когда начался, ISO 8601 UTC; null — ещё не начался
    pub started_at: Option<String>,
    /// Состояние: `queued` — ждёт очереди (у компании на паузе — до её снятия); `running` — идёт; `done` — завершён (итог — answer и proposals); `error` — не удался (почему — error; можно повторить, а при error_code = onec_offl…
    pub state: Option<Box<AutomationManualRunState>>,
    /// Итоги шагов запуска по порядку (у запусков до цепочек — пусто). Повтор упавшего запуска продолжает с упавшего шага, прошлые не повторяются
    pub steps: Option<Vec<Box<AutomationRunStep>>>,
    /// Техническая причина остановки хода ИИ (например, end_turn — штатно). Для людей — answer и error. null — хода ИИ не было или он не закончился
    pub stop_reason: Option<String>,
    /// Какие инструменты ИИ вызывал (технические имена) — для разбора запуска
    pub tools: Option<Vec<String>>,
    /// true — пробный прогон: на прошлом событии (POST …/scenarios/{id}/run с event_id) или на пробном событии хука (POST …/hooks/{id}/test с run: true). В 1С само ничего не пишется даже при правиле автоодобрения — все предложе…
    pub trial: Option<bool>,
    /// Что запустило: `hook` — событие хука (event_id); `event` — событие внутри Tungo (event_type, event_id; external_id — id события evt_…, тот же, что у вебхука); `schedule` — расписание (slot_at); `manual` — ручной запуск (…
    pub trigger: Option<Box<AutomationManualRunTrigger>>,
    pub raw: BTreeMap<String, JsonValue>,
}

