/// Что происходит: - `compacting` — сервер сжимает историю длинного разговора - `escalating` — ответ перепроверяется более сильной моделью — ход займёт дольше - `elsewhere` — ответ готовится на другом сервере Tungo — он поя…
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ChatEventCode {
    Compacting,
    Escalating,
    Elsewhere,
    UnknownValue(String),
}

impl ChatEventCode {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Compacting => "compacting",
            Self::Escalating => "escalating",
            Self::Elsewhere => "elsewhere",
            Self::UnknownValue(s) => s.as_str(),
        }
    }
}

/// Конец хода — приходит после записи хода в историю. Дальше событий не будет
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatEventDone {
    /// Итоговый ответ хода целиком (Markdown): заменить им собранный из text
    pub answer: Option<String>,
    /// При awaiting_user — id открытого вопроса
    pub choice_id: Option<String>,
    /// Сколько ход стоил, в тиынах (1 ₸ = 100 тиын). Только в потоке для ключа API (платформа разработчиков); кабинету стоимость ответа не отдаётся
    pub cost_tiyn: Option<i64>,
    /// Чем кончился ход: end_turn — ответ готов; awaiting_user — ждёт ответа на вопрос choice; budget — кончился лимит; aborted — остановили; refusal — модель отказалась; context_overflow — разговор слишком длинный; max_iterati…
    pub stop_reason: Option<String>,
    /// Вид события: done
    pub r#type: Option<String>,
    pub usage: Option<Box<ChatUsage>>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Ошибка хода — тем же видом, что ошибка REST. Поток после неё не рвётся: дальше придёт done
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatEventError {
    pub error: Option<Box<ChatTurnError>>,
    /// Номер запроса для поддержки
    pub request_id: Option<String>,
    /// Вид события: error
    pub r#type: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Исход последней строки: created — предложение создано; skipped — уже было; manual — решает человек; failed — ошибка; unknown — исход неизвестен
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ChatEventOutcome {
    Created,
    Skipped,
    Failed,
    Unknown,
    Manual,
    UnknownValue(String),
}

impl ChatEventOutcome {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Created => "created",
            Self::Skipped => "skipped",
            Self::Failed => "failed",
            Self::Unknown => "unknown",
            Self::Manual => "manual",
            Self::UnknownValue(s) => s.as_str(),
        }
    }
}

