#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatEventReport {
    pub approval: Option<Box<ChatEventReportApproval>>,
    /// Создано предложений
    pub created: Option<i64>,
    /// Повторы строки в одном источнике (тот же ключ, исход один). Одинаковые строки выписки без номера документа — разные платежи: у второй и дальше свой ключ, сюда они не входят
    pub duplicates: Option<i64>,
    /// С ошибкой
    pub failed: Option<i64>,
    /// Служебное: нагрузка на 1С
    pub gateway: Option<Box<ChatEventReportGateway>>,
    /// Ждут решения человека
    pub manual: Option<i64>,
    /// Служебное: сколько сеансов 1С пачка держала
    pub min_concurrency: Option<i64>,
    /// Не взятые в работу после остановки; повторный запуск возьмёт их
    pub pending: Option<i64>,
    /// Исход по каждой строке
    pub rows: Option<Vec<Box<BatchJobRow>>>,
    /// Пропущено (уже было)
    pub skipped: Option<i64>,
    /// true — задание остановили до конца
    pub stopped: Option<bool>,
    /// Строк в источнике
    pub total: Option<i64>,
    /// С неизвестным исходом (1С не ответила)
    pub unknown: Option<i64>,
    pub raw: BTreeMap<String, JsonValue>,
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatEventReportApproval {
    /// Одобрено, включая уже записанные раньше
    pub approved: Option<f64>,
    /// Номер задания, если одобряли по batch_id
    pub batch_id: Option<String>,
    /// Сколько предложений с каждым исходом (ключ — outcome из results)
    pub counts: Option<BTreeMap<String, f64>>,
    /// Снято галочкой
    pub excluded: Option<f64>,
    /// Не одобрено по любой причине
    pub failed: Option<f64>,
    /// Предел пачки (2000)
    pub limit: Option<f64>,
    /// Итог одной фразой для человека
    pub message: Option<String>,
    /// true — всё, что не снято галочкой, одобрено (или уже было записано); false — есть отказы, смотрите results
    pub ok: Option<bool>,
    /// Сколько предложений в пачке (со снятыми галочкой)
    pub requested: Option<f64>,
    /// Исход по каждому предложению, в порядке пачки
    pub results: Option<Vec<Box<BatchApproveResult>>>,
    /// Пачка остановлена раньше конца (1С трижды не ответила, база только для чтения, отозвали право, нажали «Остановить»)
    pub stopped: Option<Box<ChatEventReportApprovalStopped>>,
    /// Номера из exclude, которых нет в пачке
    pub unknown_excluded: Option<Vec<String>>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Пачка остановлена раньше конца (1С трижды не ответила, база только для чтения, отозвали право, нажали «Остановить»)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatEventReportApprovalStopped {
    /// Почему остановлена — текст для человека
    pub reason: Option<String>,
    /// Сколько предложений не тронуто и ждут решения
    pub remaining: Option<f64>,
    pub raw: BTreeMap<String, JsonValue>,
}

