/// Сообщение разговора: вопрос человека (role = user) или ответ ИИ (role = assistant)
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatMessage {
    /// Когда задан вопрос, ISO 8601 UTC
    pub at: Option<String>,
    /// Приложенные файлы, если были
    pub attachments: Option<Vec<Box<ChatAttachmentMeta>>>,
    /// Устойчивый id сообщения: <dialog_id>:<номер хода>:u
    pub id: Option<String>,
    /// Вопрос идущего хода: ответа ещё нет, его дочитывают потоком (GET …/chat/{id}/events?turn=). Только у последнего сообщения
    pub pending: Option<String>,
    /// Сообщение человека
    pub role: Option<String>,
    /// Текст вопроса
    pub text: Option<String>,
    /// Ответ по блокам, по порядку
    pub blocks: Option<Vec<Box<ChatHistoryBlock>>>,
    /// Источники ответа
    pub citations: Option<Vec<Box<ChatCitation>>>,
    /// Номера предложений этого хода — то же, что proposal-блоки, списком
    pub proposal_ids: Option<Vec<String>>,
    /// done — ход закончился сам; stopped — нажали «Стоп»; error — ошибка, отказ модели или предел шагов
    pub state: Option<Box<ChatAssistantMessageState>>,
    /// Размышления модели за ход одним текстом; пусто — не было
    pub thinking: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Вопрос ИИ-бухгалтеру
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ChatMessageRequest {
    /// Файлы к вопросу. До 5 файлов, каждый до 10 МБ, все вместе до 14 МБ (до кодирования в base64). Картинка — до 5 МБ, PDF — до 100 страниц. Форматы (по расширению имени): .pdf, .jpg, .jpeg, .png, .webp, .docx, .xlsx, .xls, .…
    pub attachments: Option<Vec<Box<ChatAttachment>>>,
    /// Что умеет клиент: ["choice"] — показывать уточняющие вопросы с вариантами (событие choice). Без него ИИ спрашивает обычным текстом
    pub capabilities: Option<Vec<String>>,
    /// Продолжить разговор с этим id. Без него — новый разговор, его id придёт в заголовке X-Dialog-Id
    pub dialog_id: Option<String>,
    /// Вопрос человека, до 4000 знаков; можно не писать, если приложены файлы
    pub message: Option<String>,
    /// Режим хода: auto (по умолчанию) — ИИ сам решает, ответить или подготовить документ; ask — только ответ и разбор, без документов; document — подготовить документ
    pub mode: Option<Box<ChatMessageRequestMode>>,
    /// true — начать новый разговор именно с этим dialog_id (клиент задаёт id сам); id уже занят — 409
    pub new_dialog: Option<bool>,
    /// Вопрос по предложению (кнопка «Ответить в чате» у карточки или в ленте): ход начнётся с этим предложением в контексте — ИИ увидит его номер, статус, блокеры и предупреждения. Нет такого предложения в компании — 404
    pub proposal_id: Option<String>,
    /// false — ответ одним JSON (ChatTurnResult), когда ход закончится; по умолчанию — поток SSE
    pub stream: Option<bool>,
    /// Номер последнего хода, который видел клиент (заголовок X-Turn-No): если сервер этот ход потерял (перезапуск) — 410, начните новый разговор
    pub turn: Option<i64>,
    pub raw: BTreeMap<String, JsonValue>,
}

