/// Карточка ленты: событие по предложению, вопрос ИИ, выписка дня, проверка учёта или запуск автоматизации
#[derive(Debug, Clone, Default, PartialEq)]
pub struct FeedItem {
    /// Кнопки карточки в нужном порядке
    pub actions: Option<Vec<Box<FeedAction>>>,
    /// Кто сделал: usr_… — человек, key_… — ключ API, ai — ИИ, checks — проверки учёта, automation:… — автоматизация, system — сервис
    pub actor: Option<String>,
    /// Имя того, кто сделал, для показа: имя человека, название ключа API, «ИИ-бухгалтер», «Проверки учёта», «Автоматизация»; нет — неизвестно, показать actor
    pub actor_name: Option<String>,
    pub amount: Option<Box<FeedItemAmount>>,
    /// Когда случилось, ISO 8601 UTC
    pub at: Option<String>,
    /// Задание пачки (выписка дня): сводка — GET …/batch/{batch_id}/summary
    pub batch_id: Option<String>,
    /// Курсор этого события: передавать в ?cursor= и в Last-Event-ID
    pub cursor: Option<String>,
    /// Подробности: блокеры, расхождения, текст вопроса или отчёта
    pub detail: Option<String>,
    /// Разговор чата, из которого предложение: «Открыть разговор» — GET …/chat/{dialog_id}. Нет — предложение не из чата
    pub dialog_id: Option<String>,
    /// Устойчивый id события ленты (не номер предложения): ключ для списка в интерфейсе
    pub id: Option<String>,
    /// Номер предложения (P-…), если событие про него
    pub proposal_id: Option<String>,
    pub section: Option<Box<FeedSection>>,
    /// Название раздела по-русски
    pub section_title: Option<String>,
    pub status: Option<Box<ProposalStatus>>,
    /// Статус предложения по-русски
    pub status_title: Option<String>,
    /// Заголовок карточки
    pub title: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

