/// Ошибка одного поля запроса
#[derive(Debug, Clone, Default, PartialEq)]
pub struct FieldError {
    /// Что не так: invalid_type — не тот тип или поле не передано; too_small / too_big — короче/меньше или длиннее/больше допустимого; invalid_format — неверный вид (почта, дата, шаблон); invalid_value — значения нет среди допу…
    pub code: Option<Box<FieldErrorCode>>,
    /// Текст для человека по-русски — показать под полем
    pub message: Option<String>,
    /// Путь к полю через точку, как в теле запроса или имени параметра: `name`, `lines.0.amount`. Пустая строка — всё тело (не объект, лишние поля).
    pub path: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Что не так: invalid_type — не тот тип или поле не передано; too_small / too_big — короче/меньше или длиннее/больше допустимого; invalid_format — неверный вид (почта, дата, шаблон); invalid_value — значения нет среди допу…
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FieldErrorCode {
    InvalidType,
    TooSmall,
    TooBig,
    InvalidFormat,
    InvalidValue,
    NotMultipleOf,
    UnrecognizedKeys,
    InvalidUnion,
    InvalidKey,
    InvalidElement,
    Custom,
    UnknownValue(String),
}

impl FieldErrorCode {
    pub fn as_str(&self) -> &str {
        match self {
            Self::InvalidType => "invalid_type",
            Self::TooSmall => "too_small",
            Self::TooBig => "too_big",
            Self::InvalidFormat => "invalid_format",
            Self::InvalidValue => "invalid_value",
            Self::NotMultipleOf => "not_multiple_of",
            Self::UnrecognizedKeys => "unrecognized_keys",
            Self::InvalidUnion => "invalid_union",
            Self::InvalidKey => "invalid_key",
            Self::InvalidElement => "invalid_element",
            Self::Custom => "custom",
            Self::UnknownValue(s) => s.as_str(),
        }
    }
}

