/// Сам файл JSON для «Загрузить (JSON)» в КНП ИСНА — сохранить как есть (Content-Disposition: attachment с именем файла), не разбирать
pub type IsnaFile = BTreeMap<String, JsonValue>;

/// IsnaSummary при summary=1, иначе сам файл IsnaFile
#[derive(Debug, Clone, Default, PartialEq)]
pub struct IsnaResponse {
    /// Можно ли скачать файл (GET …/forms/isna без summary)
    pub available: Option<bool>,
    /// Можно ли загружать как есть (кроме ручной шапки): форма полная, всё посчитано и легло в файл
    pub complete: Option<bool>,
    /// Где скачать файл в приложении
    pub download: Option<Box<IsnaResponseDownload>>,
    /// Сколько ячеек расчёта легло в файл
    pub exported: Option<i64>,
    /// Имя файла JSON для КНП ИСНА
    pub file_name: Option<String>,
    /// Реквизиты шапки, которые человек заполняет в КНП сам
    pub for_human: Option<Vec<String>>,
    /// Код формы (бланка), например 300.00 — декларация по НДС
    pub form: Option<String>,
    /// Формат файла
    pub format: Option<Box<IsnaResponseFormat>>,
    /// Откуда взято каждое значение шапки: реквизит → источник
    pub header_from: Option<BTreeMap<String, String>>,
    /// Почему файл неполный
    pub incomplete_because: Option<Vec<String>>,
    /// Редакция бланка 1С, по чьей карте собран файл
    pub map_edition: Option<String>,
    /// Что делать человеку с файлом в КНП ИСНА — по шагам
    pub next: Option<String>,
    /// Сколько ячеек бланка наш расчёт не считает: в КНП останутся пустыми, если их не заполнить
    pub not_in_calculation: Option<i64>,
    /// Период формы
    pub period: Option<Box<IsnaResponsePeriod>>,
    /// Итог сверки с отчётом 1С
    pub reconciliation: Option<Box<IsnaResponseReconciliation>>,
    /// Ячейки расчёта, которых нет в карте: в файл не попали, перенести руками
    pub unmapped: Option<Vec<String>>,
    /// Предупреждения
    pub warnings: Option<Vec<String>>,
    pub raw: BTreeMap<String, JsonValue>,
}

