/// Состояние подключения к 1С без настроек и секретов
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OneCStatus {
    /// Подключена ли 1С
    pub connected: Option<bool>,
    /// Как Tungo достаёт данные 1С: odata — живая 1С через интернет; connector — коробочная 1С в офисе через программу Tungo Connector; snapshot — загруженная копия базы, только чтение; fake — только в тестах; null — не подключ…
    pub gateway: Option<Box<OneCGateway>>,
    /// Итог последней проверки; null — не проверялось или не подключена
    pub last_check: Option<Box<OneCStatusLastCheck>>,
    /// Когда подключение меняли, ISO 8601 UTC; null — не подключена
    pub updated_at: Option<String>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Итог последней проверки; null — не проверялось или не подключена
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OneCStatusLastCheck {
    /// Что ИИ сможет делать
    pub capabilities: Option<Vec<Box<OneCCapability>>>,
    /// Когда проверено, ISO 8601 UTC
    pub checked_at: Option<String>,
    /// true — проверка по прежней версии настроек
    pub stale: Option<bool>,
    /// Итог одной фразой
    pub summary: Option<String>,
    /// Итог: ok — всё в порядке; warn — работать можно, но не всё (смотрите checks); fail — работать нельзя
    pub verdict: Option<Box<OneCStatusLastCheckVerdict>>,
    pub raw: BTreeMap<String, JsonValue>,
}

/// Итог: ok — всё в порядке; warn — работать можно, но не всё (смотрите checks); fail — работать нельзя
