/// Что ИИ предлагает записать в 1С (подпись по-русски — в kind_title): - sale — реализация товаров и услуг (продажа покупателю); - purchase — поступление товаров и услуг (покупка у поставщика); - bank_receipt — входящее пла…
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ProposalKind {
    Sale,
    Purchase,
    BankReceipt,
    BankPayment,
    Counterparty,
    Contract,
    Revert,
    InventoryWriteoff,
    CashOrderIn,
    CashOrderOut,
    AdvanceReport,
    UnknownValue(String),
}

impl ProposalKind {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Sale => "sale",
            Self::Purchase => "purchase",
            Self::BankReceipt => "bank_receipt",
            Self::BankPayment => "bank_payment",
            Self::Counterparty => "counterparty",
            Self::Contract => "contract",
            Self::Revert => "revert",
            Self::InventoryWriteoff => "inventory_writeoff",
            Self::CashOrderIn => "cash_order_in",
            Self::CashOrderOut => "cash_order_out",
            Self::AdvanceReport => "advance_report",
            Self::UnknownValue(s) => s.as_str(),
        }
    }
}

